-- RepairMitra Store: products + variants + orders + order items + safe stock reduction
create extension if not exists pgcrypto;
create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,category text not null,brand text,model text,sku text unique,price numeric(12,2) not null default 0,purchase_price numeric(12,2) default 0,stock_quantity integer not null default 0 check(stock_quantity>=0),low_stock_limit integer not null default 5,image_url text,description text,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.product_variants(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,variant_name text not null,variant_value text not null,stock_quantity integer not null default 0 check(stock_quantity>=0),created_at timestamptz not null default now(),unique(product_id,variant_name,variant_value));
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),customer_id uuid not null,customer_name text not null,phone text not null,address text not null,city text not null,pincode text not null,total_amount numeric(12,2) not null default 0,payment_method text not null default 'COD',payment_status text not null default 'pending',status text not null default 'Pending',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid not null references public.products(id),product_name text not null,price numeric(12,2) not null,quantity integer not null check(quantity>0),line_total numeric(12,2) not null);
create index if not exists order_customer_idx on public.orders(customer_id);create index if not exists order_status_idx on public.orders(status);create index if not exists order_items_order_idx on public.order_items(order_id);
create or replace function public.place_store_order(p_customer_name text,p_phone text,p_address text,p_city text,p_pincode text,p_items jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare v_order uuid;v_item jsonb;v_product products%rowtype;v_qty int;v_total numeric(12,2):=0;begin if auth.uid() is null then raise exception 'Login required';end if;if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception 'Cart is empty';end if;for v_item in select * from jsonb_array_elements(p_items) loop v_qty:=greatest(1,(v_item->>'quantity')::int);select * into v_product from products where id=(v_item->>'product_id')::uuid and is_active=true for update;if not found then raise exception 'Product unavailable';end if;if v_product.stock_quantity<v_qty then raise exception 'Insufficient stock for %',v_product.name;end if;v_total:=v_total+(v_product.price*v_qty);end loop;insert into orders(customer_id,customer_name,phone,address,city,pincode,total_amount,payment_method,payment_status,status)values(auth.uid(),p_customer_name,p_phone,p_address,p_city,p_pincode,v_total,'COD','pending','Pending') returning id into v_order;for v_item in select * from jsonb_array_elements(p_items) loop v_qty:=greatest(1,(v_item->>'quantity')::int);select * into v_product from products where id=(v_item->>'product_id')::uuid for update;update products set stock_quantity=stock_quantity-v_qty,updated_at=now() where id=v_product.id;insert into order_items(order_id,product_id,product_name,price,quantity,line_total)values(v_order,v_product.id,v_product.name,v_product.price,v_qty,v_product.price*v_qty);end loop;return v_order;end;$$;
revoke all on function public.place_store_order(text,text,text,text,text,jsonb) from public;grant execute on function public.place_store_order(text,text,text,text,text,jsonb) to authenticated;
create or replace function public.cancel_store_order(p_order_id uuid) returns boolean language plpgsql security definer set search_path=public as $$declare r orders%rowtype;i order_items%rowtype;begin if not exists(select 1 from orders where id=p_order_id) then raise exception 'Order not found';end if;select * into r from orders where id=p_order_id for update;if r.status='Cancelled' then return true;end if;for i in select * from order_items where order_id=p_order_id loop update products set stock_quantity=stock_quantity+i.quantity,updated_at=now() where id=i.product_id;end loop;update orders set status='Cancelled',updated_at=now() where id=p_order_id;return true;end;$$;
revoke all on function public.cancel_store_order(uuid) from public;grant execute on function public.cancel_store_order(uuid) to authenticated;
alter table products enable row level security;alter table product_variants enable row level security;alter table orders enable row level security;alter table order_items enable row level security;
drop policy if exists products_public_active_read on products;create policy products_public_active_read on products for select using(is_active=true);
drop policy if exists variants_public_read on product_variants;create policy variants_public_read on product_variants for select using(true);
drop policy if exists orders_customer_read on orders;create policy orders_customer_read on orders for select using(customer_id=auth.uid() or (to_regprocedure('public.is_admin()') is not null and public.is_admin()));
drop policy if exists order_items_customer_read on order_items;create policy order_items_customer_read on order_items for select using(exists(select 1 from orders o where o.id=order_id and (o.customer_id=auth.uid() or (to_regprocedure('public.is_admin()') is not null and public.is_admin()))));
-- Admin writes remain protected by existing admin policies/project setup; add them only if your is_admin() helper is available.
